<?php
function nstPayrollSlipContext($db,$id){
 $s=$db->prepare("SELECT p.*,e.Empleado,e.DniRuc,e.Direccion,e.Telefono,pp.Cargo,pp.FechaIngreso,pp.Banco,pp.NumeroCuenta,pp.CCI,pp.Titular,pp.DatosLaborales,a.Almacen FROM Rhu_PlanillaPeriodo p JOIN Rhu_Empleado e ON e.IdEmpleado=p.IdEmpleado LEFT JOIN Rhu_PlanillaPersonal pp ON pp.IdEmpleado=p.IdEmpleado LEFT JOIN Lo_Almacen a ON a.IdAlmacen=pp.IdAlmacen WHERE p.IdPlanilla=?");$s->execute([(int)$id]);$p=$s->fetch(PDO::FETCH_ASSOC);if(!$p)throw new InvalidArgumentException('No existe la liquidacion del trabajador.');$p['Detalle']=json_decode($p['Detalle'],true);$p['Laborales']=json_decode($p['DatosLaborales']?:'{}',true)?:[];unset($p['DatosLaborales']);$p=array_merge($p,nstPayrollCycle($p['Periodo'],$p['FechaIngreso']));
 $company=$db->query('SELECT RAZONSOCIAL,RUC,DIRECCION FROM Gen_Empresa LIMIT 1')->fetch(PDO::FETCH_ASSOC)?:[];
 $s=$db->prepare('SELECT pg.IdPago,pg.Fecha,pg.Tipo,pg.Importe,pg.Referencia,pg.UsuarioReg,c.Cuenta FROM Rhu_PlanillaPago pg JOIN Cb_CajaBanco cb ON cb.IdCajaBanco=pg.IdCajaBanco JOIN Cb_Cuenta c ON c.IdCuenta=pg.IdCuenta WHERE pg.IdPlanilla=? AND pg.Anulado=0 AND IFNULL(cb.Anulado,0)=0 ORDER BY pg.Fecha,pg.IdPago');$s->execute([(int)$id]);$payments=$s->fetchAll(PDO::FETCH_ASSOC);
 $s=$db->prepare('SELECT IdBoleta,Version,FechaReg,UsuarioReg,HashDocumento FROM Rhu_PlanillaBoleta WHERE IdPlanilla=? ORDER BY Version DESC');$s->execute([(int)$id]);return ['planilla'=>$p,'empresa'=>$company,'pagos'=>$payments,'boletas'=>$s->fetchAll(PDO::FETCH_ASSOC)];
}
function nstPayrollSlipSnapshot($ctx,$labor,$attendance,$user){
 $p=$ctx['planilla'];$company=$ctx['empresa'];if(empty($company['RAZONSOCIAL'])||!preg_match('/^[0-9]{11}$/',(string)($company['RUC']??'')))throw new InvalidArgumentException('Complete razon social y RUC de la empresa.');
 if(empty($p['FechaIngreso'])||empty($p['Cargo'])||empty($p['DniRuc']))throw new InvalidArgumentException('Complete fecha de ingreso, cargo y documento del personal.');
 $legal=[];foreach(['TipoDocumento','Categoria','CUSPP','CodigoAsegurado','Sexo','Nacionalidad','Direccion','FechaNacimiento','FechaCese','DetalleOtrosDescuentos','DetalleOtrosAportes'] as $key){$legal[$key]=trim((string)($labor[$key]??''));if(strlen($legal[$key])>250)throw new InvalidArgumentException('Revise los datos laborales.');}
 if(!in_array($legal['TipoDocumento'],['DNI','CE','PASAPORTE','PTP','OTRO'],true)||$legal['Categoria']==='')throw new InvalidArgumentException('Indique tipo de documento y categoria del trabajador.');
 foreach(['FechaNacimiento','FechaCese'] as $key)if($legal[$key]!==''&&!nstPayrollDate($legal[$key]))throw new InvalidArgumentException('Fecha laboral invalida.');
 if(($p['Detalle']['Pension']??'NINGUNO')==='AFP'&&$legal['CUSPP']==='')throw new InvalidArgumentException('Ingrese el CUSPP del trabajador afiliado a AFP.');
 $time=[];foreach(['DiasLaborados','DiasSubsidiados','DiasNoLaborados','HorasOrdinarias','HorasExtras'] as $key){if(!isset($attendance[$key])||$attendance[$key]===''||!is_numeric($attendance[$key])||$attendance[$key]<0)throw new InvalidArgumentException('Complete los dias y horas segun el control de asistencia.');$time[$key]=round((float)$attendance[$key],2);}
 foreach(['DiasLaborados','DiasSubsidiados','DiasNoLaborados'] as $key)if($time[$key]>31||floor($time[$key])!==$time[$key])throw new InvalidArgumentException('Los dias deben ser enteros entre 0 y 31.');
 if(array_sum(array_intersect_key($time,array_flip(['DiasLaborados','DiasSubsidiados','DiasNoLaborados'])))>31||$time['HorasOrdinarias']>744||$time['HorasExtras']>744)throw new InvalidArgumentException('Revise los totales de asistencia.');
 foreach(['VacacionesDesde','VacacionesHasta'] as $key){$time[$key]=(string)($attendance[$key]??'');if($time[$key]!==''&&!nstPayrollDate($time[$key]))throw new InvalidArgumentException('Fecha de vacaciones invalida.');}
 if(($time['VacacionesDesde']==='')!==($time['VacacionesHasta']==='')||($time['VacacionesDesde']&&$time['VacacionesDesde']>$time['VacacionesHasta']))throw new InvalidArgumentException('Complete un rango valido de vacaciones.');
 $time['Aportes']=[];foreach(['EsSalud','VidaLey','SCTR','Otros'] as $key)$time['Aportes'][$key]=nstPayrollMoney($attendance['Aportes'][$key]??0);if(abs(round(array_sum($time['Aportes']),2)-round((float)($p['Detalle']['AporteEmpleador']??0),2))>0.001)throw new InvalidArgumentException('El detalle de aportes del empleador debe coincidir con el total registrado en la liquidacion.');if(($p['Detalle']['OtrosDescuentos']??0)>0&&$legal['DetalleOtrosDescuentos']==='')throw new InvalidArgumentException('Describa los otros descuentos del trabajador.');if($time['Aportes']['Otros']>0&&$legal['DetalleOtrosAportes']==='')throw new InvalidArgumentException('Describa los otros aportes del empleador.');
 $paid=0;$advance=0;foreach($ctx['pagos'] as $pg){$paid+=(float)$pg['Importe'];if($pg['Tipo']==='ADELANTO')$advance+=(float)$pg['Importe'];}
 return ['empresa'=>$company,'trabajador'=>['Nombre'=>$p['Empleado'],'Documento'=>$p['DniRuc'],'Cargo'=>$p['Cargo'],'FechaIngreso'=>$p['FechaIngreso'],'Almacen'=>$p['Almacen'],'Banco'=>$p['Banco'],'NumeroCuenta'=>$p['NumeroCuenta'],'CCI'=>$p['CCI'],'Titular'=>$p['Titular'],'Legal'=>$legal],'Periodo'=>$p['Periodo'],'InicioCiclo'=>$p['InicioCiclo'],'FinCiclo'=>$p['FinCiclo'],'FechaProgramada'=>$p['FechaPagoPeriodo'],'Conceptos'=>$p['Detalle'],'Pagos'=>$ctx['pagos'],'TotalPagado'=>round($paid,2),'TotalAdelantos'=>round($advance,2),'Saldo'=>max(0,round((float)$p['Neto']-$paid,2)),'Asistencia'=>$time,'Representante'=>'BLANCA MARTINEZ BRAVO','CargoRepresentante'=>'Gerente general','UsuarioEmisor'=>$user,'FechaEmision'=>(new DateTime('now',new DateTimeZone('America/Lima')))->format('Y-m-d H:i:s')];
}
function nstPayrollSlipHtml($data,$number='MODELO'){
 $e=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};$m=function($v){return 'S/ '.number_format((float)$v,2,'.',',');};$d=function($v){return $v?implode('/',array_reverse(explode('-',substr($v,0,10)))):'-';};$w=$data['trabajador'];$c=$data['Conceptos'];$t=$data['Asistencia'];$l=$w['Legal'];
 $income=['Sueldo'=>'Remuneracion basica','Comision'=>'Comisiones','Asignacion'=>'Asignacion familiar / remunerativa','OtrosIngresos'=>'Otros ingresos remunerativos','Vacaciones'=>'Remuneracion vacacional'];$non=['CTS'=>'CTS','Gratificacion'=>'Gratificacion','BonoGratificacion'=>'Bonificacion extraordinaria'];$deductions=['AportePension'=>($c['Pension']??'').' - aporte pensionario','SeguroAFP'=>'Prima de seguro AFP','ComisionAFP'=>'Comision AFP','RentaQuinta'=>'Retencion quinta categoria','OtrosDescuentos'=>($l['DetalleOtrosDescuentos']??'')?:'Otros descuentos'];
 $rows=function($items)use($c,$e,$m){$out='';foreach($items as $key=>$label)$out.='<tr><td>'.$e($label).'</td><td class="money">'.$m($c[$key]??0).'</td></tr>';return $out;};
 $employerRows='';foreach(['EsSalud'=>'EsSalud','VidaLey'=>'Seguro Vida Ley','SCTR'=>'SCTR','Otros'=>($l['DetalleOtrosAportes']??'')?:'Otros aportes'] as $key=>$label){$amount=$t['Aportes'][$key]??0;if($amount>0)$employerRows.='<tr><td>'.$e($label).'</td><td class="money">'.$m($amount).'</td></tr>';}if(!$employerRows)$employerRows='<tr><td>Sin aportes registrados</td><td class="money">'.$m(0).'</td></tr>';
 $payments='';foreach($data['Pagos'] as $pg)$payments.='<tr><td>'.$d($pg['Fecha']).'</td><td>'.$e($pg['Tipo']).'</td><td>'.$e($pg['Cuenta']).'</td><td>'.$e($pg['Referencia']?:'-').'</td><td class="money">'.$m($pg['Importe']).'</td></tr>';
 if(!$payments)$payments='<tr><td colspan="5">Sin abonos registrados. Pendiente de pago.</td></tr>';
 $status=$data['TotalPagado']<=0?'PENDIENTE DE PAGO':($data['Saldo']>0?'PAGO PARCIAL':'PAGO REGISTRADO');$model=($data['Modelo']??false)?'<div class="model">MODELO DE PRUEBA - SIN VALIDEZ COMO CONSTANCIA DE PAGO</div>':'';
 $html='<!doctype html><html lang="es"><head><meta charset="utf-8"><style>@page{margin:24px 30px}body{font-family:DejaVu Sans,sans-serif;color:#19394b;font-size:8.5px;line-height:1.3}table{border-collapse:collapse;width:100%}td,th{padding:4px 7px;vertical-align:top}th{background:#123f53;color:white;text-align:left;font-size:8px}h1{font-size:20px;margin:3px 0}h2{font-size:10px;margin:11px 0 5px;color:#087b82}.head{border-bottom:3px solid #0a969b;padding-bottom:10px}.head td{padding:0}.right{text-align:right}.muted{color:#6c8392;font-size:8px}.info td{border:1px solid #d6e4eb}.info b{display:block;font-size:7px;color:#648293;margin-bottom:2px}.columns>tbody>tr>td{width:50%;padding:0 6px 0 0}.concepts td{border-bottom:1px solid #edf1f4}.money{text-align:right;white-space:nowrap}.total td{background:#e9f3f5;font-weight:bold;border-top:1px solid #c6dde4}.summary td{background:#e7f3ef;border:2px solid white;padding:9px;font-size:10px}.summary b{font-size:14px;display:block}.sign td{width:50%;text-align:center;padding:24px 20px 0}.line{border-top:1px solid #849ba8;padding-top:5px}.model{background:#fff0c9;color:#856100;padding:7px;font-size:9px;font-weight:bold;margin-bottom:8px}.status{font-weight:bold;color:#087966}.foot{font-size:7px;color:#6a7e8b;border-top:1px solid #dbe4e9;margin-top:6px;padding-top:4px}.payments td{font-size:8px;border-bottom:1px solid #e0e9ef}.avoid{page-break-inside:avoid}</style></head><body>'.$model.'<table class="head"><tr><td style="width:61%"><strong>'.$e($data['empresa']['RAZONSOCIAL']).'</strong><br>RUC: '.$e($data['empresa']['RUC']).'<br><span class="muted">'.$e($data['empresa']['DIRECCION']??'').'</span></td><td class="right"><h1>BOLETA DE PAGO</h1><b>Periodo '.$e($data['Periodo']).'</b><br>Nro. '.$e($number).'<br><span class="muted">D.S. 001-98-TR / R.M. 020-2008-TR</span></td></tr></table><h2>TRABAJADOR Y RELACION LABORAL</h2><table class="info"><tr><td colspan="2"><b>APELLIDOS Y NOMBRES</b>'.$e($w['Nombre']).'</td><td><b>DOCUMENTO</b>'.$e($l['TipoDocumento']).' '.$e($w['Documento']).'</td></tr><tr><td><b>CARGO / CATEGORIA</b>'.$e($w['Cargo']).' / '.$e($l['Categoria']).'</td><td><b>INGRESO / CESE</b>'.$d($w['FechaIngreso']).' / '.$d($l['FechaCese']).'</td><td><b>REGIMEN LABORAL</b>'.$e($c['Regimen']??'GENERAL').'</td></tr><tr><td><b>REGIMEN PENSIONARIO / AFP</b>'.$e($c['Pension']).' '.$e($c['AFP']??'').'</td><td><b>CUSPP / CODIGO ASEGURADO</b>'.$e($l['CUSPP']?:$l['CodigoAsegurado']?:'-').'</td><td><b>SEDE / CENTRO DE TRABAJO</b>'.$e($w['Almacen']?:'-').'</td></tr><tr><td colspan="2"><b>DOMICILIO</b>'.$e($l['Direccion']?:'-').'</td><td><b>NACIONALIDAD / SEXO / NACIMIENTO</b>'.$e($l['Nacionalidad']?:'-').' / '.$e($l['Sexo']?:'-').' / '.$d($l['FechaNacimiento']).'</td></tr><tr><td><b>CICLO REMUNERATIVO</b>'.$d($data['InicioCiclo']).' al '.$d($data['FinCiclo']).'</td><td><b>FECHA PROGRAMADA DE PAGO</b>'.$d($data['FechaProgramada']).'</td><td><b>ESTADO DE ABONOS REGISTRADOS</b><span class="status">'.$status.'</span></td></tr></table><h2>ASISTENCIA DEL PERIODO</h2><table class="info"><tr><td><b>DIAS LABORADOS</b>'.$e($t['DiasLaborados']).'</td><td><b>DIAS SUBSIDIADOS</b>'.$e($t['DiasSubsidiados']).'</td><td><b>DIAS NO LABORADOS / NO SUBSIDIADOS</b>'.$e($t['DiasNoLaborados']).'</td><td><b>HORAS ORDINARIAS</b>'.$e($t['HorasOrdinarias']).'</td><td><b>HORAS EN SOBRETIEMPO</b>'.$e($t['HorasExtras']).'</td></tr></table><div class="muted">Vacaciones: salida '.$d($t['VacacionesDesde']).' / retorno '.$d($t['VacacionesHasta']).'</div><table class="columns"><tr><td><h2>INGRESOS REMUNERATIVOS</h2><table class="concepts">'.$rows($income).'</table><h2>OTROS PAGOS NO REMUNERATIVOS</h2><table class="concepts">'.$rows($non).'<tr class="total"><td>TOTAL INGRESOS</td><td class="money">'.$m($c['Ingresos']).'</td></tr></table></td><td><h2>DEDUCCIONES Y APORTES DEL TRABAJADOR</h2><table class="concepts">'.$rows($deductions).'<tr class="total"><td>TOTAL DESCUENTOS</td><td class="money">'.$m($c['Descuentos']).'</td></tr></table><h2>APORTES A CARGO DEL EMPLEADOR</h2><table class="concepts">'.$employerRows.'<tr class="total"><td>TOTAL APORTES EMPLEADOR</td><td class="money">'.$m($c['AporteEmpleador']??0).'</td></tr></table><div class="muted">Los aportes del empleador no reducen el neto del trabajador.</div></td></tr></table><table class="summary avoid"><tr><td>NETO DEL PERIODO<b>'.$m($c['Neto']).'</b></td><td>ADELANTOS ABONADOS<b>'.$m($data['TotalAdelantos']).'</b></td><td>TOTAL ABONADO<b>'.$m($data['TotalPagado']).'</b></td><td>SALDO POR ABONAR<b>'.$m($data['Saldo']).'</b></td></tr></table><h2>ABONOS Y ADELANTOS REGISTRADOS</h2><table class="payments"><tr><th>Fecha</th><th>Concepto</th><th>Cuenta de salida</th><th>Referencia / operacion</th><th class="right">Importe</th></tr>'.$payments.'</table><p class="muted">Destino: '.$e(trim(($w['Banco']??'').' '.($w['NumeroCuenta']??''))?:'Sin cuenta bancaria registrada').' | CCI: '.$e($w['CCI']?:'-').' | Titular: '.$e($w['Titular']?:$w['Nombre']).'</p><div class="avoid"><table class="sign"><tr><td><div class="line"><b>'.$e($data['Representante']).'</b><br>'.$e($data['CargoRepresentante']).'<br>Firma y sello del empleador</div></td><td><div class="line"><b>'.$e($w['Nombre']).'</b><br>'.$e($l['TipoDocumento']).' '.$e($w['Documento']).'<br>Firma / constancia de recepcion del trabajador</div></td></tr></table></div><div class="foot">Emitida: '.$e($data['FechaEmision']).' | Usuario: '.$e($data['UsuarioEmisor']).'<br>La generacion de esta boleta no constituye una firma digital ni acredita por si sola el abono bancario. Conservar la constancia de pago y de entrega. No reemplaza la declaracion de planilla electronica.</div></body></html>';
 return $html;
}
function nstPayrollSlipPdf($html,$base=null){ob_start();try{$base=$base?:__DIR__.'/sunat/plugins/dompdf';require_once $base.'/lib/html5lib/Parser.php';require_once $base.'/lib/php-font-lib/src/FontLib/Autoloader.php';require_once $base.'/lib/php-svg-lib/src/autoload.php';require_once $base.'/src/Autoloader.php';Dompdf\Autoloader::register();$pdf=new Dompdf\Dompdf();$pdf->set_paper('A4','portrait');$pdf->load_html($html);$pdf->render();return $pdf->output();}finally{ob_end_clean();}}
return function($app,$auth){
 $app->get('/planilla/boleta/datos',function($q,$r)use($auth){return $auth->bindTo($this)($q,$r,function($user)use($q,$r){return $r->withJson(nstPayrollSlipContext($this->db,(int)$q->getParam('IdPlanilla')));});});
 $app->post('/planilla/boleta/emitir',function($q,$r)use($auth){return $auth->bindTo($this)($q,$r,function($user)use($q,$r){$db=$this->db;$id=(int)$q->getParam('IdPlanilla');$db->beginTransaction();$s=$db->prepare('SELECT IdPlanilla FROM Rhu_PlanillaPeriodo WHERE IdPlanilla=? FOR UPDATE');$s->execute([$id]);if(!$s->fetchColumn())throw new InvalidArgumentException('Liquidacion no encontrada.');$ctx=nstPayrollSlipContext($db,$id);$snapshot=nstPayrollSlipSnapshot($ctx,$q->getParam('Laborales')?:[],$q->getParam('Asistencia')?:[],$user);$json=json_encode($snapshot,JSON_UNESCAPED_UNICODE);$hash=hash('sha256',$json);$s=$db->prepare('SELECT IdBoleta FROM Rhu_PlanillaBoleta WHERE IdPlanilla=? AND HashDocumento=? ORDER BY IdBoleta DESC LIMIT 1');$s->execute([$id,$hash]);if($old=$s->fetchColumn()){$db->commit();return $r->withJson(['IdBoleta'=>$old]);}$s=$db->prepare('SELECT IFNULL(MAX(Version),0)+1 FROM Rhu_PlanillaBoleta WHERE IdPlanilla=?');$s->execute([$id]);$version=(int)$s->fetchColumn();$s=$db->prepare('INSERT INTO Rhu_PlanillaBoleta(IdPlanilla,Version,Datos,HashDocumento,UsuarioReg,FechaReg) VALUES(?,?,?,?,?,NOW())');$s->execute([$id,$version,$json,$hash,$user]);$issued=(int)$db->lastInsertId();$s=$db->prepare('UPDATE Rhu_PlanillaPersonal SET DatosLaborales=? WHERE IdEmpleado=?');$s->execute([json_encode($snapshot['trabajador']['Legal'],JSON_UNESCAPED_UNICODE),$ctx['planilla']['IdEmpleado']]);$db->commit();return $r->withJson(['IdBoleta'=>$issued]);});});
 $app->get('/planilla/boleta/{id}/pdf',function($q,$r,$args)use($auth){return $auth->bindTo($this)($q,$r,function($user)use($q,$r,$args){$s=$this->db->prepare('SELECT * FROM Rhu_PlanillaBoleta WHERE IdBoleta=?');$s->execute([(int)$args['id']]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row)throw new InvalidArgumentException('Boleta no encontrada.');$data=json_decode($row['Datos'],true);$number=str_pad($row['IdBoleta'],6,'0',STR_PAD_LEFT).'-V'.$row['Version'];$pdf=nstPayrollSlipPdf(nstPayrollSlipHtml($data,$number));$r->getBody()->write($pdf);return $r->withHeader('Content-Type','application/pdf')->withHeader('Cache-Control','private, no-store')->withHeader('Content-Disposition','inline; filename="Boleta_Pago_'.$data['Periodo'].'_'.$row['IdBoleta'].'.pdf"');});});
};
